"use strict";

const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const destination = path.join(root, "bookmarklet/smashmate-card.js");
const sources = ["tracking.js", "bookmarklet/source.js"];
const bundle =
  "// Generated by npm run build:bookmarklet. Edit tracking.js or bookmarklet/source.js.\n" +
  "(function () {\n\"use strict\";\n" +
  sources.map((file) => fs.readFileSync(path.join(root, file), "utf8").trimEnd()).join("\n\n") +
  "\n})();\n";

if (process.argv.includes("--check")) {
  if (!fs.existsSync(destination) || fs.readFileSync(destination, "utf8") !== bundle) {
    console.error("Bookmarklet bundle is stale. Run npm run build:bookmarklet.");
    process.exitCode = 1;
  }
} else {
  fs.writeFileSync(destination, bundle);
}
